mapper.select:
select  from ecom_sub_merchant
where applyment_state in ('CHECKING','ACCOUNT_NEED_VERIFY','AUDITING','NEED_SIGN')
order by id limit #{limit}

mapper.update:
update ecom_sub_merchant set applyment_state_desc = #{stateDesc}, sign_url = #{signUrl},
    last_queried_at = current_timestamp(3)
where id = #{id}

update ecom_profit_share_return set state = #{state}, wx_return_no = coalesce(#{wxReturnNo}, wx_return_no),
    fail_reason = #{failReason}
where id = #{id} and state = #{expectedState}

mapper.select:
select id, out_payout_no as outPayoutNo, creator_member_id as creatorMemberId, source_type as sourceType, source_id as sourceId, amount_fen as amountFen, provider, state, provider_ref as providerRef, fail_reason as failReason
from creator_payout_request
where source_type = #{sourceType} and source_id = #{sourceId} and creator_member_id = #{creatorMemberId}

mapper.update:
update creator_payout_request set state = #{state}, provider_ref = coalesce(#{providerRef}, provider_ref),
    fail_reason = #{failReason}
where id = #{id} and state = #{expectedState}

mapper.select:
select  from ecom_refund
where state in #{st}
order by updated_at desc limit #{limit}

select  from ecom_sub_merchant
applyment_state = #{state}
order by updated_at desc limit #{limit}

select  from ecom_profit_share_order

    state = #{state}
    and topic_id = #{topicId}

order by id desc limit #{limit}

select id, out_return_no as outReturnNo, share_order_id as shareOrderId, out_refund_no as outRefundNo, return_mchid as returnMchid, amount_fen as amountFen, state, wx_return_no as wxReturnNo, fail_reason as failReason, return_type as returnType, return_appid as returnAppid
from ecom_profit_share_return
state = #{state}
order by id desc limit #{limit}
